input.command:
cd /Users/stef/Projects/ehlcodacabana-final/data/package && sqlite3 -header -column world.sqlite "
select kind, count(*) n, min(date), max(date) from documents group by kind;
select id,date,kind,supplier_id,part_ids,subject,asked_pct,asked_price,effective_date from documents where asked_pct is not null or date>='2026-08-01' order by date;
select purpose,status,count(*) from rfqs group by 1,2;
select type,count(*),round(avg(asked_pct),2) ask,round(avg(settled_pct),2) settled from negotiation_history group by type;
select category, count(*) n, sum(detail='full') full from suppliers group by category order by n desc;
"

cd /Users/stef/Projects/ehlcodacabana-final/data/package && sqlite3 -header -column world.sqlite "
select note, count(*) n, round(avg(asked_pct),2) ask, round(avg(settled_pct),2) settled, round(avg(settled_pct/nullif(asked_pct,0)),2) ratio from negotiation_history group by note order by n desc;
select remarks, count(*) from quotes group by remarks order by 2 desc;
select missing_fields, count(*) from quotes group by 1;
select r.purpose, q.part_id, q.supplier_id, q.unit_price, q.payment_days, q.lead_time_days, q.incoterm, q.tooling_eur, q.awarded from quotes q join rfqs r on r.id=q.rfq_id where r.purpose!='periodic benchmark' order by q.part_id;
select topic, count(*) from news group by 1 order by 2 desc;
select defect, count(*), sum(supplier_caused) from quality_notifications group by 1 order by 2 desc;
"

sqlite3 -header -column world.sqlite "
select id, supplier_id, topic, headline from news where topic!='noise' order by date;
select supplier_id, part_id, count(*) from negotiation_history where note!='' group by 1,2;
select supplier_id, remarks from quotes where remarks!='' group by 1,2;"
